B.app=new A.eg("\u041d\u0430 \u0432\u0456\u0434\u043c\u0456\u043d\u0443 \u0432\u0456\u0434 \u0437\u0432\u0438\u0447\u0430\u0439\u043d\u0438\u0445 \u0437\u0443\u0431\u043d\u0438\u0445 \u043f\u0440\u043e\u0442\u0435\u0437\u0456\u0432, \u0442\u0430\u043a\u0430 \u043a\u043e\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0456\u044f \u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u0437\u0430\u043a\u0440\u0438\u0432\u0430\u0454 \xab\u0434\u0456\u0440\u043a\u0443\xbb \u0432 \u0437\u0443\u0431\u043d\u043e\u043c\u0443 \u0440\u044f\u0434\u0443, \u0430 \u043f\u043e\u0432\u043d\u043e\u0446\u0456\u043d\u043d\u043e \u043f\u0435\u0440\u0435\u0434\u0430\u0454 \u0436\u0443\u0432\u0430\u043b\u044c\u043d\u0435 \u043d\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0435\u043d\u043d\u044f \u043d\u0430 \u043a\u0456\u0441\u0442\u043a\u0443. \u0426\u0435 \u0432\u043a\u0440\u0430\u0439 \u0432\u0430\u0436\u043b\u0438\u0432\u043e, \u043e\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0431\u0435\u0437 \u043d\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0435\u043d\u043d\u044f \u043a\u0456\u0441\u0442\u043a\u043e\u0432\u0430 \u0442\u043a\u0430\u043d\u0438\u043d\u0430 \u043f\u043e\u0447\u0438\u043d\u0430\u0454 \u043f\u043e\u0441\u0442\u0443\u043f\u043e\u0432\u043e \u0437\u043c\u0435\u043d\u0448\u0443\u0432\u0430\u0442\u0438\u0441\u044f \u0432 \u043e\u0431'\u0454\u043c\u0456. \u041e\u0442\u0436\u0435, \u0456\u043c\u043f\u043b\u0430\u043d\u0442\u0430\u0446\u0456\u044f \u0437\u0443\u0431\u0456\u0432 \u0441\u0442\u0430\u0454 \u0456\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0456\u0454\u044e \u0443 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f \u0437\u0434\u043e\u0440\u043e\u0432'\u044f \u0441\u0443\u0441\u0456\u0434\u043d\u0456\u0445 \u0437\u0443\u0431\u0456\u0432 \u0442\u0430 \u043a\u043e\u043d\u0442\u0443\u0440\u0456\u0432 \u043e\u0431\u043b\u0438\u0447\u0447\u044f.",null)
B.apq=new A.eg("\u041f\u0438\u0442\u0430\u043d\u043d\u044f \u0449\u043e \u043a\u0440\u0430\u0449\u0435 \u0456\u043c\u043f\u043b\u0430\u043d\u0442 \u0447\u0438 \u043c\u0456\u0441\u0442 \u0432\u0438\u043d\u0438\u043a\u0430\u0454 \u0434\u043e\u0441\u0438\u0442\u044c \u0447\u0430\u0441\u0442\u043e. \u0422\u0440\u0430\u0434\u0438\u0446\u0456\u0439\u043d\u0438\u0439 \u043c\u043e\u0441\u0442\u043e\u043f\u043e\u0434\u0456\u0431\u043d\u0438\u0439 \u0437\u0443\u0431\u043d\u0438\u0439 \u043f\u0440\u043e\u0442\u0435\u0437 \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u0454 \u043e\u0431\u0442\u043e\u0447\u0443\u0432\u0430\u043d\u043d\u044f \u0441\u0443\u0441\u0456\u0434\u043d\u0456\u0445 \u0437\u0443\u0431\u0456\u0432, \u044f\u043a\u0456 \u0431\u0435\u0440\u0443\u0442\u044c \u043d\u0430 \u0441\u0435\u0431\u0435 \u0432\u0441\u0435 \u043d\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0435\u043d\u043d\u044f. \u041d\u0430\u0442\u043e\u043c\u0456\u0441\u0442\u044c \u0437\u0443\u0431\u043d\u0438\u0439 \u0456\u043c\u043f\u043b\u0430\u043d\u0442 \u0454 \u0430\u0432\u0442\u043e\u043d\u043e\u043c\u043d\u0438\u043c: \u0432\u0456\u043d \u043d\u0435 \u0440\u0443\u0439\u043d\u0443\u0454 \u0441\u0443\u0441\u0456\u0434\u043d\u0456 \u0437\u0443\u0431\u0438. \u0425\u043e\u0447\u0430 \u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u0456 \u0432\u0438\u0442\u0440\u0430\u0442\u0438 \u043c\u043e\u0436\u0443\u0442\u044c \u0437\u0434\u0430\u0442\u0438\u0441\u044f \u0432\u0438\u0449\u0438\u043c\u0438, \u043f\u043e\u0440\u0456\u0432\u043d\u044e\u044e\u0447\u0438 \u2013 \u0456\u043c\u043f\u043b\u0430\u043d\u0442\u0430\u0446\u0456\u044f \u0447\u0438 \u043f\u0440\u043e\u0442\u0435\u0437\u0443\u0432\u0430\u043d\u043d\u044f \u043c\u043e\u0441\u0442\u0430\u043c\u0438, \u043f\u0435\u0440\u0448\u0438\u0439 \u0432\u0430\u0440\u0456\u0430\u043d\u0442 \u0447\u0430\u0441\u0442\u043e \u0432\u0438\u044f\u0432\u043b\u044f\u0454\u0442\u044c\u0441\u044f \u0431\u0456\u043b\u044c\u0448 \u0432\u0438\u0433\u0456\u0434\u043d\u0438\u043c, \u043e\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u043d\u0435 \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u0454 \u0437\u0430\u043c\u0456\u043d\u0438 \u043a\u043e\u0436\u043d\u0456 7\u201310 \u0440\u043e\u043a\u0456\u0432.",null)
B.apr=new A.eg("\u0406\u043c\u043f\u043b\u0430\u043d\u0442\u0430\u0446\u0456\u044f \u0437\u0443\u0431\u0456\u0432 \u2013 \u0446\u0435 \u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u043c\u0435\u0434\u0438\u0447\u043d\u0430 \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430, \u0430 \u043c\u043e\u0436\u043b\u0438\u0432\u0456\u0441\u0442\u044c \u0437\u043d\u043e\u0432\u0443 \u0432\u0456\u0434\u0447\u0443\u0432\u0430\u0442\u0438 \u0441\u043c\u0430\u043a \u0436\u0438\u0442\u0442\u044f \u0442\u0430 \u0441\u043c\u0456\u044f\u0442\u0438\u0441\u044f \u0431\u0435\u0437 \u0441\u043e\u0440\u043e\u043c\u0443. \u0426\u0435 \u0440\u0456\u0448\u0435\u043d\u043d\u044f \u043f\u0456\u0434\u0445\u043e\u0434\u0438\u0442\u044c \u043c\u0430\u0439\u0436\u0435 \u0432\u0441\u0456\u043c, \u0445\u0442\u043e \u0432\u0442\u0440\u0430\u0442\u0438\u0432 \u0437\u0443\u0431\u0438 \u0447\u0435\u0440\u0435\u0437 \u0442\u0440\u0430\u0432\u043c\u0438 \u0447\u0438 \u0445\u0432\u043e\u0440\u043e\u0431\u0438. \u0413\u043e\u043b\u043e\u0432\u043d\u0435 \u2013 \u043f\u0430\u043c'\u044f\u0442\u0430\u0442\u0438, \u0449\u043e \u0441\u0443\u0447\u0430\u0441\u043d\u0456 \u0441\u0442\u043e\u043c\u0430\u0442\u043e\u043b\u043e\u0433\u0456\u043d\u0456 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0456\u0457 \u0434\u0430\u044e\u0442\u044c \u0437\u043c\u043e\u0433\u0443 \u0437\u0440\u043e\u0431\u0438\u0442\u0438 \u0448\u043b\u044f\u0445 \u0434\u043e \u0456\u0434\u0435\u0430\u043b\u044c\u043d\u043e\u0457 \u0443\u0441\u043c\u0456\u0448\u043a\u0438 \u043a\u043e\u043c\u0444\u043e\u0440\u0442\u043d\u0438\u043c. \u042f\u043a\u0449\u043e \u0432\u0438 \u043e\u0431\u0438\u0440\u0430\u0454\u0442\u0435 \u043c\u0456\u0436 \u0432\u0430\u0440\u0456\u0430\u043d\u0442\u0430\u043c\u0438 \u2013 \u0456\u043c\u043f\u043b\u0430\u043d\u0442 \u0447\u0438 \u043c\u0456\u0441\u0442, \u043f\u0430\u043c'\u044f\u0442\u0430\u0439\u0442\u0435: \u043d\u0430 \u043a\u043e\u0436\u0435\u043d \u0432\u0438\u043f\u0430\u0434\u043e\u043a \u0454 \u0440\u0456\u0448\u0435\u043d\u043d\u044f, \u0456 \u0437\u043d\u0430\u0439\u0442\u0438 \u0439\u043e\u0433\u043e \u043c\u043e\u0436\u043d\u0430 \u043f\u0456\u0434 \u0447\u0430\u0441 \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0442\u0430\u0446\u0456\u0457 \u0456\u0437 \u0444\u0430\u0445\u0456\u0432\u0446\u0435\u043c.",null)
B.aps=new A.eg("\u041f\u0456\u0434 \u0447\u0430\u0441 \u043c\u0430\u043d\u0456\u043f\u0443\u043b\u044f\u0446\u0456\u0457 \u0432\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u043e\u0432\u0443\u0454\u0442\u044c\u0441\u044f \u0435\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u0430 \u043c\u0456\u0441\u0446\u0435\u0432\u0430 \u0430\u043d\u0435\u0441\u0442\u0435\u0437\u0456\u044f, \u044f\u043a\u0430 \u043f\u043e\u0432\u043d\u0456\u0441\u0442\u044e \u0431\u043b\u043e\u043a\u0443\u0454 \u0447\u0443\u0442\u043b\u0438\u0432\u0456\u0441\u0442\u044c \u0443 \u0437\u043e\u043d\u0456 \u0441\u0442\u043e\u043c\u0430\u0442\u043e\u043b\u043e\u0433\u0456\u0447\u043d\u043e\u0457 \u043c\u0430\u043d\u0456\u043f\u0443\u043b\u044f\u0446\u0456\u0457. \u0414\u043b\u044f \u0442\u0438\u0445, \u0445\u0442\u043e \u0432\u0456\u0434\u0447\u0443\u0432\u0430\u0454 \u0441\u0438\u043b\u044c\u043d\u0438\u0439 \u0441\u0442\u0440\u0435\u0441, \u0454 \u0441\u0435\u0434\u0430\u0446\u0456\u044f (\u043c\u0435\u0434\u0438\u043a\u0430\u043c\u0435\u043d\u0442\u043e\u0437\u043d\u0438\u0439 \u0441\u043e\u043d). \u0423 \u0442\u0430\u043a\u043e\u043c\u0443 \u0441\u0442\u0430\u043d\u0456 \u043f\u0430\u0446\u0456\u0454\u043d\u0442 \u0432\u0456\u0434\u043f\u043e\u0447\u0438\u0432\u0430\u0454, \u0430 \u043b\u0456\u043a\u0430\u0440-\u0441\u0442\u043e\u043c\u0430\u0442\u043e\u043b\u043e\u0433 \u043c\u043e\u0436\u0435 \u0441\u043f\u043e\u043a\u0456\u0439\u043d\u043e \u0442\u0430 \u0442\u043e\u0447\u043d\u043e \u0432\u0438\u043a\u043e\u043d\u0430\u0442\u0438 \u0441\u0432\u043e\u044e \u0440\u043e\u0431\u043e\u0442\u0443. \u041f\u0456\u0441\u043b\u044f \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u043d\u044f \u0434\u0456\u0457 \u0430\u043d\u0435\u0441\u0442\u0435\u0437\u0456\u0457 \u043c\u043e\u0436\u0435 \u0441\u043f\u043e\u0441\u0442\u0435\u0440\u0456\u0433\u0430\u0442\u0438\u0441\u044f \u043d\u0435\u0437\u043d\u0430\u0447\u043d\u0438\u0439 \u0431\u043e\u043b\u044c\u043e\u0432\u0438\u0439 \u0434\u0438\u0441\u043a\u043e\u043c\u0444\u043e\u0440\u0442 \u0443 \u0437\u043e\u043d\u0456 \u0456\u043c\u043f\u043b\u0430\u043d\u0442\u0430\u0446\u0456\u0457 \u0437\u0443\u0431\u0430, \u0430\u043b\u0435 \u0432\u0456\u043d \u043b\u0435\u0433\u043a\u043e \u0443\u0441\u0443\u0432\u0430\u0454\u0442\u044c\u0441\u044f \u0437\u0432\u0438\u0447\u0430\u0439\u043d\u0438\u043c\u0438 \u0437\u043d\u0435\u0431\u043e\u043b\u044e\u0432\u0430\u043b\u044c\u043d\u0438\u043c\u0438 \u0437\u0430\u0441\u043e\u0431\u0430\u043c\u0438.",null)
B.apt=new A.eg("\u0412\u0442\u0440\u0430\u0442\u0430 \u043d\u0430\u0432\u0456\u0442\u044c \u043e\u0434\u043d\u043e\u0433\u043e \u0437\u0443\u0431\u0430 \u2013 \u0446\u0435 \u043d\u0435 \u043b\u0438\u0448\u0435 \u0435\u0441\u0442\u0435\u0442\u0438\u0447\u043d\u0435 \u043f\u0438\u0442\u0430\u043d\u043d\u044f, \u0430 \u0439 \u0432\u0438\u043a\u043b\u0438\u043a \u0434\u043b\u044f \u0437\u0434\u043e\u0440\u043e\u0432'\u044f \u0432\u0441\u0456\u0454\u0457 \u0449\u0435\u043b\u0435\u043f\u0438. \u0421\u0443\u0447\u0430\u0441\u043d\u0430 \u0441\u0442\u043e\u043c\u0430\u0442\u043e\u043b\u043e\u0433\u0456\u044f \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0454 \u043d\u0430\u0434\u0456\u0439\u043d\u0438\u0439 \u0432\u0438\u0445\u0456\u0434, \u044f\u043a\u0438\u0439 \u0434\u043e\u0437\u0432\u043e\u043b\u044f\u0454 \u0437\u0430\u0431\u0443\u0442\u0438 \u043f\u0440\u043e \u0434\u0438\u0441\u043a\u043e\u043c\u0444\u043e\u0440\u0442 \u0456 \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0432\u043f\u0435\u0432\u043d\u0435\u043d\u0443 \u043f\u043e\u0441\u043c\u0456\u0448\u043a\u0443. \u041d\u0438\u0436\u0447\u0435 \u0434\u0435\u0442\u0430\u043b\u044c\u043d\u043e \u0440\u043e\u0437\u0431\u0435\u0440\u0435\u043c\u043e, \u0449\u043e \u0442\u0430\u043a\u0435 \u0456\u043c\u043f\u043b\u0430\u043d\u0442\u0430\u0446\u0456\u044f \u0437\u0443\u0431\u0456\u0432 \u0442\u0430 \u044f\u043a\u0438\u0445 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0456\u0432 \u0432\u0430\u0440\u0442\u043e \u043e\u0447\u0456\u043a\u0443\u0432\u0430\u0442\u0438 \u0432\u0456\u0434 \u0446\u0456\u0454\u0457 \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0438. \u041d\u0430\u0448\u0430 \u043c\u0435\u0442\u0430 \u2013 \u043d\u0430\u0434\u0430\u0442\u0438 \u0432\u0438\u0447\u0435\u0440\u043f\u043d\u0443 \u0456\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u044e, \u0449\u043e\u0431 \u0432\u0438 \u043c\u043e\u0433\u043b\u0438 \u0432\u043f\u0435\u0432\u043d\u0435\u043d\u043e \u043d\u0430\u0432\u0430\u0436\u0438\u0442\u0438\u0441\u044c \u043d\u0430 \u0434\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u0443 \u0456\u043c\u043f\u043b\u0430\u043d\u0442\u0430\u0446\u0456\u044e, \u0430\u0434\u0436\u0435 \u043d\u0430 \u043a\u043e\u0436\u0435\u043d \u0441\u043a\u043b\u0430\u0434\u043d\u0438\u0439 \u0432\u0438\u043f\u0430\u0434\u043e\u043a \u0437\u0430\u0432\u0436\u0434\u0438 \u0454 \u0440\u0456\u0448\u0435\u043d\u043d\u044f. \u0422\u0430\u043a\u0438\u0439 \u043f\u0456\u0434\u0445\u0456\u0434 \u0434\u043e\u043f\u043e\u043c\u0430\u0433\u0430\u0454 \u0437\u0440\u043e\u0437\u0443\u043c\u0456\u0442\u0438, \u044f\u043a \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442\u044c \u0456\u043c\u043f\u043b\u0430\u043d\u0442\u0430\u0446\u0456\u044f \u0442\u0430 \u0447\u043e\u043c\u0443 \u0432\u043e\u043d\u0430 \u0441\u0442\u0430\u0454 \u043d\u0430\u0434\u0456\u0439\u043d\u0438\u043c \u0432\u0430\u0440\u0456\u0430\u043d\u0442\u043e\u043c \u0434\u043b\u044f \u0432\u0456\u0434\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0443\u0441\u043c\u0456\u0448\u043a\u0438.",null)
B.apu=new A.eg("\u0422\u0430\u043a\u0430 \u043f\u043e\u0441\u043b\u0456\u0434\u043e\u0432\u043d\u0456\u0441\u0442\u044c \u0434\u0456\u0439 \u0433\u0430\u0440\u0430\u043d\u0442\u0443\u0454 \u043f\u0435\u0440\u0435\u0434\u0431\u0430\u0447\u0443\u0432\u0430\u043d\u0438\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0456 \u0432\u0438\u0441\u043e\u043a\u0438\u0439 \u0432\u0456\u0434\u0441\u043e\u0442\u043e\u043a \u0443\u0441\u043f\u0456\u0445\u0443 \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0438. \u041e\u0437\u043d\u0430\u0439\u043e\u043c\u0438\u0442\u0438\u0441\u044f \u0437 \u0432\u0430\u0440\u0456\u0430\u043d\u0442\u0430\u043c\u0438 \u043b\u0456\u043a\u0443\u0432\u0430\u043d\u043d\u044f \u0442\u0430 \u0434\u0435\u0442\u0430\u043b\u044c\u043d\u0456\u0448\u0435 \u0434\u0456\u0437\u043d\u0430\u0442\u0438\u0441\u044f \u043f\u0440\u043e \u0456\u043c\u043f\u043b\u0430\u043d\u0442\u0430\u0446\u0456\u044e \u0437\u0443\u0431\u0456\u0432 \u043c\u043e\u0436\u043d\u0430 \u043d\u0430 \u0441\u0442\u043e\u0440\u0456\u043d\u0446\u0456 \u043f\u043e\u0441\u043b\u0443\u0433\u0438.",null)
